<?php
require_once __DIR__.'/app/lib/Db.php';require_once __DIR__.'/app/lib/Security.php';require_once __DIR__.'/app/lib/VendorSelfService.php';Security::start();$u=Security::user();if(!$u){header('Location:/login?next=/vendor-portal');exit;}$pdo=Db::pdo();$vendors=$pdo->query("SELECT id,name,slug,website_url,verification_status FROM vendors WHERE status='active' ORDER BY name")->fetchAll(PDO::FETCH_ASSOC);$members=VendorSelfService::memberships($pdo,(int)$u['id']);$csrf=Security::csrf();
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Vendor Portal | TechSelectAI</title><style>body{font-family:system-ui;margin:0;background:#f6f8fb;color:#172033}.wrap{max-width:1080px;margin:auto;padding:28px}.card{background:#fff;border:1px solid #dfe6ee;border-radius:16px;padding:20px;margin:16px 0}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:12px}input,select,textarea,button{width:100%;box-sizing:border-box;padding:10px;border:1px solid #ccd6e0;border-radius:9px}button{background:#123b67;color:#fff;font-weight:700;cursor:pointer}.muted{color:#667085;font-size:14px}.pill{display:inline-block;padding:4px 8px;border-radius:999px;background:#eef4f8;font-size:12px}</style></head><body><div class="wrap"><h1>Verified Vendor Portal</h1><p class="muted">Claim your company profile, then submit factual updates for review. TechSelectAI scores, rankings, community intelligence and recommendations remain editorially independent.</p><section class="card"><h2>Claim a company</h2><div class="grid"><select id="claimVendor"><option value="">Select company</option><?php foreach($vendors as $v):?><option value="<?=$v['id']?>"><?=htmlspecialchars($v['name'])?></option><?php endforeach?></select><select id="claimMethod"><option value="company_domain_email">Company-domain email</option><option value="official_website_evidence">Official website evidence</option><option value="manufacturer_directory">Manufacturer directory</option><option value="admin_documentation">Admin-reviewed documentation</option></select><input id="companyEmail" placeholder="name@company.com"><input id="claimUrl" placeholder="Evidence URL"></div><textarea id="claimNote" placeholder="Evidence / explanation" rows="3"></textarea><button onclick="claimVendor()">Submit claim</button></section><section class="card"><h2>Your verified companies</h2><?php if(!$members):?><p class="muted">No verified company memberships yet.</p><?php else:foreach($members as $m):?><p><strong><?=htmlspecialchars($m['vendor_name'])?></strong> <span class="pill"><?=htmlspecialchars($m['verification_status'])?></span></p><?php endforeach;endif?></section><section class="card"><h2>Suggest a factual update</h2><div class="grid"><select id="updVendor"><option value="">Verified company</option><?php foreach($members as $m):?><option value="<?=$m['vendor_id']?>"><?=htmlspecialchars($m['vendor_name'])?></option><?php endforeach?></select><select id="updType"><option value="company_profile">Company profile</option><option value="product_url">Product URL</option><option value="pricing">Pricing</option><option value="documentation">Documentation</option><option value="security">Security</option><option value="integrations">Integrations</option><option value="territory">Territory</option><option value="compliance">Compliance</option><option value="acquisition">Acquisition</option><option value="feature_removal">Feature removal</option><option value="broken_url">Broken URL</option><option value="other_fact">Other factual update</option></select><input id="productId" placeholder="Product ID (optional)"><input id="fieldKey" placeholder="Field key, e.g. pricing_url"><input id="currentValue" placeholder="Current value"><input id="proposedValue" placeholder="Proposed value"><input id="updEvidence" placeholder="Evidence URL"></div><textarea id="updNotes" placeholder="Notes" rows="3"></textarea><button onclick="submitUpdate()">Submit update for review</button></section><p id="msg" class="muted"></p></div><script>const csrf=<?php echo json_encode($csrf)?>;async function post(url,b){let r=await fetch(url,{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-Token':csrf},body:JSON.stringify(b)});let j=await r.json();document.getElementById('msg').textContent=j.error||'Submitted successfully';if(r.ok)setTimeout(()=>location.reload(),600)}function claimVendor(){post('/api/vendor-self-service/claim',{vendor_id:+claimVendorEl().value,verification_method:claimMethod.value,company_email:companyEmail.value,evidence_url:claimUrl.value,evidence_note:claimNote.value})}function claimVendorEl(){return document.getElementById('claimVendor')}function submitUpdate(){post('/api/vendor-self-service/update',{vendor_id:+updVendor.value,product_id:productId.value?+productId.value:null,update_type:updType.value,field_key:fieldKey.value,current_value:currentValue.value,proposed_value:proposedValue.value,evidence_url:updEvidence.value,notes:updNotes.value})}</script></body></html>